import {esc as e,fmt as f} from './lib.js?v=20261031-player6';
import {speedSummary} from './evidence.js?v=20261031-player6';
import {metricSummary,protocolOf} from './core-metrics.js?v=20261031-player6';

const ms=x=>x==null?'—':f(x/1000,2)+' s';

export function speedView(data,taskId='all'){
  const protocols=new Set(data.runs.map(protocolOf));
  if(protocols.has('core-client-v1')||data.meta?.protocolId==='core-client-v1')return coreSpeedView(data,taskId);
  return `<p class="count-line">当前任务：${data.tasks.map(t=>e(t.title)).join("、")||"无"}</p><div class="notice">当前运行器并发为 1。这里衡量客户端看到的单请求体验；网络、服务商排队与分块都会影响数值。不能由此推断模型内部解码速度或并发吞吐。</div>
  <section class="panel"><div class="panel-head"><h2>速度与请求结果</h2><small>成功请求经验分位数 · 不把失败当作零延迟</small></div><div class="table-wrap"><table><thead><tr><th>模型配置</th><th>尝试 / 成功 / 失败</th><th>超时</th><th>首内容事件 P50</th><th>首正文 P50</th><th>完整耗时 P50</th><th>完整耗时 P90</th><th>正文 TPS P50</th><th>字符/秒 P50</th></tr></thead><tbody>${data.models.map(m=>{const s=speedSummary(data,m.id,taskId);return `<tr><td><button class="link" data-model="${e(m.id)}">${e(m.name)}</button></td><td>${s.attempted} / ${s.success} / ${s.errors}</td><td>${s.timeouts}</td><td>${ms(s.ttft)}</td><td>${ms(s.ttfa)}</td><td>${ms(s.duration)}<small>${s.durationSamples} 个样本</small></td><td>${ms(s.p90)}<small>${s.durationSamples<20?'小样本描述值':'经验分位数'}</small></td><td>${f(s.tps)}<small>${s.tpsSamples} 个可测速率样本</small></td><td>${f(s.cps)}</td></tr>`}).join('')}</tbody></table></div><div class="table-foot">P50/P90 对成功请求的实际数值做线性插值；小样本 P90 不代表长期服务承诺。失败与超时在独立列保留，须同时阅读。</div></section>
  <div class="grid2"><section class="panel"><div class="panel-body"><h2>什么时候显示 TPS？</h2><p>至少 3 个非空正文分块，首末正文间隔不少于 0.5 秒，且能识别至少 64 个可见输出 token。缺少推理 token 分账时，正文 TPS 留空。</p><p>字符速率排除第一个分块，后续至少 64 个 Unicode 字符。字符不是 token，不能混用。</p></div></section><section class="panel"><div class="panel-body"><h2>比较前先对齐条件</h2><p>先在顶部选择同一批次，再选择同一任务。输出长度、推理设置、服务商、客户端位置和采集时段都会改变体验。</p><p>当前样本较少；同题重复用于检查该任务的稳定性，不增加独立题目数。速度差异需要更多时段复核。</p><a href="#method">查看完整方法 ↗</a></div></section></div>`;
}

function coreSpeedView(data,taskId){
  const scoped=taskId==='all'?data:{...data,runs:data.runs.filter(r=>r.taskId===taskId)};
  return `<div class="notice">核心协议 v1 · 客户端单请求体验。并发吞吐与模型内部解码速度尚未测量；网络、排队和分块会影响数值。不同协议的TPS独立列出。</div><section class="panel"><div class="panel-head"><h2>等待、输出与失败</h2><small>成功请求中位数；未知留空</small></div><div class="table-wrap"><table><thead><tr><th>配置</th><th>尝试 / 完整返回 / 失败</th><th>首内容 / 首正文</th><th>完整耗时 P50 / P95</th><th>正文TPS · 新</th><th>端到端正文TPS</th><th>字符/秒 · 新</th><th>旧TPS边界估计</th></tr></thead><tbody>${scoped.models.map(m=>{const s=metricSummary(scoped,m.id);return `<tr><td><button class="link" data-model="${e(m.id)}">${e(m.name)}</button></td><td>${s.attempted} / ${s.success} / ${s.errors}<small>${s.timeouts}次超时 · ${s.truncated}次截断</small></td><td>${ms(s.ttft)} / ${ms(s.ttfa)}</td><td>${ms(s.duration)} / ${ms(s.durationP95)}<small>${s.durationSamples}个成功样本；${s.tailState==='available'?'同条件≥100':s.tailState==='mixed_conditions'?'混合条件不列P95':'少于100不列P95'}</small></td><td>${f(s.bodyTps)}<small>${s.bodyTpsSamples}个可测样本</small></td><td>${f(s.endToEndTps)}<small>${s.endToEndTpsSamples}个可测样本；含等待</small></td><td>${f(s.chars)}<small>${s.charsSamples}个可测样本</small></td><td>${f(s.legacyTps)}<small>${s.legacyTpsSamples}个旧样本</small></td></tr>`}).join('')}</tbody></table></div></section><div class="grid2"><section class="panel"><div class="panel-body prose"><h2>TPS为何可能为空</h2><p>新正文TPS先减去首个正文块的token，再除以首末正文时间差。可靠的可见总量、可靠首块计数、3个正文块、0.5秒、首块之后64个token必须同时满足。</p><p>当前真实适配器没有可靠首块token计数，新正文TPS会留空；端到端速率与字符速率在各自条件满足时仍可计算。模拟计数器只验证程序，不代表真实tokenizer。</p><p>字符/秒也排除首块，至少64个后续Unicode字符。分块间隔不是ITL。</p></div></section><section class="panel"><div class="panel-body prose"><h2>如何公平比较</h2><p>先用顶部筛选同一协议、批次与任务。进一步控制输入输出长度、服务商、推理档位、地区、缓存和时段。当前试点记录不能支持总体速度排名。</p><p>失败与待评不填成零延迟或通过。少量重复不能代表长期可靠性，核心P95须同条件至少100个成功样本。</p><a href="#method">查看公式与历史口径 ↗</a>　<a href="#metrics">查看质量与合格结果费用 ↗</a></div></section></div>`;
}
